#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int dau = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 1) dau++;
    }
    printf("%d %d\n", dau, n - dau);
    return 0;
}
